"""Training task factos_utilizador (phase 8, DECISIONS D50), generated by code: no model, no network.

    .venv/bin/python tools/make_user_facts.py generate [--out DIR]   training/data-v5/factos_utilizador/{train,held_out}.jsonl, INDEX.json
    .venv/bin/python tools/make_user_facts.py real                   training/real-questions/factos-v1.jsonl from factos-v1.questions.jsonl

Step 1 of answering a person: a question in plain Portuguese -> the facts of the procedure it states, in the engine's
vocabulary (tools/read_rules.VOCAB, preco_base, data_inicio_procedimento); a fact the question does not state is left
out, never guessed. The engine (code) then applies the settled rules; the model never answers the law.
Every vocabulary item (contract objects, places, entities, procedure verbs, number and date formats, sentence layouts,
asides, final questions) is either train-only or held-out-only, so held_out measures wordings never trained. A second,
hand-written set (training/real-questions/, not generated by any template here) is the transfer test.
"""
import argparse
import hashlib
import json
import random
import sys
from datetime import date, timedelta
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT)); sys.path.insert(0, str(ROOT / "tools"))
import make_training as mt  # noqa: E402
import read_rules  # noqa: E402  (the engine's fact vocabulary)
from engine.canon import sha256_text  # noqa: E402

VERSION = "ccp-make-user-facts-0.1"
DATA = ROOT / "training/data-v5"
REAL = ROOT / "training/real-questions"
TASK = "factos_utilizador"
N_TRAIN, N_HELD = 4000, 400
SEED = 20261027
FIELDS = ["tipo_entidade", "tipo_procedimento", "tipo_contrato", "territorio", "preco_base", "publicado_joue", "data_inicio_procedimento"]
OPENING = "És um leitor de perguntas sobre contratação pública. Extrai da pergunta os factos do procedimento que ela afirma e responde com um objeto JSON e nada mais."
RULES_LINE = ("Regras: em «factos» põe só os factos que a pergunta afirma, com estes campos e valores: "
              + "; ".join(f"{k}: {', '.join(json.dumps(v, ensure_ascii=False) for v in vals)}" for k, vals in read_rules.VOCAB.items())
              + "; preco_base: número em euros; data_inicio_procedimento: uma data no formato ISO (ano-mês-dia). "
              "Um facto que a pergunta não afirma fica de fora; não o deduzas nem o adivinhes.")
MONTHS = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"]

# value -> (train phrases, held-out phrases). Each phrase is a noun phrase used after «para» / «com».
OBJECTS = {
    "obras": (["a construção de uma escola", "a reabilitação do mercado municipal", "a pavimentação da estrada municipal",
               "a ampliação do centro de saúde", "a construção de uma rotunda", "uma empreitada de obras públicas"],
              ["a construção de uma piscina", "a requalificação da praça central", "a reparação da ponte",
               "a construção de um pavilhão desportivo"]),
    "bens": (["a compra de computadores", "a aquisição de mobiliário escolar", "a compra de viaturas elétricas",
              "o fornecimento de papel"],
             ["a compra de fardamento", "a aquisição de equipamento médico", "o fornecimento de combustível"]),
    "servicos": (["o serviço de limpeza dos edifícios", "os serviços de segurança e vigilância", "a manutenção dos elevadores",
                  "a consultoria jurídica"],
                 ["a recolha de resíduos", "o serviço de refeições escolares", "o transporte escolar", "uma auditoria financeira"]),
}
PLACES = {
    "PT": (["em Braga", "no Porto", "em Lisboa", "em Coimbra"], ["em Viseu", "em Faro", "em Évora"]),
    "PT-AC": (["em Ponta Delgada", "em Angra do Heroísmo", "nos Açores"], ["na Horta", "na ilha do Pico"]),
    "PT-MA": (["no Funchal", "no Porto Santo", "na Madeira"], ["em Machico", "em Câmara de Lobos"]),
}
ENTITIES = {
    "outra": (["Somos uma câmara municipal", "Sou técnico de uma junta de freguesia"], ["Trabalhamos num município", "Sou da autarquia"]),
    "estado": (["Trabalho num ministério", "Represento uma direção-geral do Estado"], ["Escrevo da secretaria-geral de um ministério"]),
}
PROCS = {  # value -> (with article, bare)
    "concurso_publico": ("um concurso público", "concurso público"), "ajuste_direto": ("um ajuste direto", "ajuste direto"),
    "consulta_previa": ("uma consulta prévia", "consulta prévia"),
    "concurso_limitado_previa_qualificacao": ("um concurso limitado por prévia qualificação", "concurso limitado por prévia qualificação"),
    "procedimento_negociacao": ("um procedimento de negociação", "procedimento de negociação"),
    "dialogo_concorrencial": ("um diálogo concorrencial", "diálogo concorrencial"),
    "parceria_inovacao": ("uma parceria para a inovação", "parceria para a inovação"),
}
JOUE = {  # True / False / None (the question says it is not known: no fact)
    True: (["Vamos publicar o anúncio no Jornal Oficial da União Europeia.", "O anúncio vai ao JOUE."],
           ["O anúncio também sai no jornal oficial europeu."]),
    False: (["Não vamos publicar no Jornal Oficial da União Europeia.", "Não há anúncio no JOUE."],
            ["O anúncio só sai no Diário da República."]),
    None: (["Ainda não decidimos se publicamos no JOUE."], ["Não sei se tem de ir ao jornal oficial europeu."]),
}
PRICE = (["O preço base é de {x}.", "Fixámos um preço base de {x}."], ["Preço base: {x}.", "O preço base ficou em {x}."])
START = (["O procedimento começa {d}.", "Tem início {d}."], ["Arranca {d}.", "Abrimos o procedimento {d}."])
ASIDES = (["O contrato dura 12 meses.", "Esperamos umas cinco propostas."], ["A obra deve ficar pronta no próximo ano.", "Já falámos com dois fornecedores."])
TARGETS = (["Quantos dias temos de dar para as propostas?", "Que prazo mínimo se aplica?", "Que regras temos de cumprir?", "Podemos avançar assim?"],
           ["Qual é o prazo para apresentar propostas?", "O que diz a lei sobre isto?", "Há algum limite que devamos respeitar?"])
PRICES = [8_500, 19_900, 48_000, 75_000, 139_000, 221_000, 250_000, 480_000, 980_000, 1_200_000, 2_500_000, 5_538_000, 6_000_000]


def money(n, split, rng):
    if split == "train":
        forms = [f"{n:,} euros".replace(",", " "), "€ " + f"{n:,}".replace(",", ".")] + ([f"{n // 1000} mil euros"] if n % 1000 == 0 else [])
    else:
        forms = [f"{n:,}".replace(",", ".") + "€", f"{n:,}".replace(",", " ") + ",00 EUR"]
        if n >= 1_000_000 and n % 100_000 == 0:
            forms.append(f"{n / 1_000_000:g}".replace(".", ",") + " milhões de euros")
    return rng.choice(forms)


def when(d, today, split, rng):
    if split == "train":
        forms = [f"a {d.day} de {MONTHS[d.month - 1]} de {d.year}", f"em {d.isoformat()}"] + (["hoje"] if d == today else [])
    else:
        forms = [f"a {d.day:02d}/{d.month:02d}/{d.year}"] + ([f"no dia {d.day} de {MONTHS[d.month - 1]}"] if d.year == today.year else []) \
            + (["amanhã"] if d == today + timedelta(days=1) else [])
    return rng.choice(forms)


def schema():
    props = {k: {"type": "string", "enum": v} for k, v in read_rules.VOCAB.items() if k != "publicado_joue"}
    props["publicado_joue"] = {"type": "boolean"}
    props["preco_base"] = {"type": "number"}
    props["data_inicio_procedimento"] = {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
    return {"type": "object", "properties": {"factos": {"type": "object", "properties": props, "additionalProperties": False}},
            "required": ["factos"], "additionalProperties": False}


def prompt(question, today):
    return "\n".join([OPENING, RULES_LINE, f"Data de hoje: {today}.", "", "Pergunta: " + question])


def answer(facts):
    return json.dumps({"factos": {k: facts[k] for k in FIELDS if k in facts}}, ensure_ascii=False, separators=(",", ":"))


def one(rng, split):
    """A person's question and the facts it states. Each fact is present with its own probability; a layout joins them."""
    s = 0 if split == "train" else 1
    today = date(2026, 1, 1) + timedelta(days=rng.randrange(540))
    facts, sentences = {}, []
    ent = rng.choice(list(ENTITIES)) if rng.random() < 0.6 else None
    proc = rng.choice(list(PROCS)) if rng.random() < 0.75 else None
    kind = rng.choice(list(OBJECTS)) if rng.random() < 0.75 else None
    terr = rng.choice(list(PLACES)) if rng.random() < 0.5 else None
    obj = rng.choice(OBJECTS[kind][s]) if kind else None
    place = rng.choice(PLACES[terr][s]) if terr else None
    for f, v in (("tipo_entidade", ent), ("tipo_procedimento", proc), ("tipo_contrato", kind), ("territorio", terr)):
        if v:
            facts[f] = v
    if s == 0:
        core = (f"vamos lançar {PROCS[proc][0]} para {obj}" if proc and obj else f"vamos lançar {PROCS[proc][0]}" if proc
                else f"precisamos de avançar com {obj}" if obj else "estamos a preparar um procedimento")
    else:
        core = (f"o procedimento é {PROCS[proc][0]} e o objeto é {obj}" if proc and obj else f"o procedimento escolhido é {PROCS[proc][0]}" if proc
                else f"o objetivo é {obj}" if obj else "temos um procedimento em preparação")
    core += f" {place}" if place else ""
    lead = f"{rng.choice(ENTITIES[ent][s])} e {core}." if ent else core[0].upper() + core[1:] + "."
    extras = []
    if rng.random() < 0.4:
        n = rng.choice(PRICES); facts["preco_base"] = n
        extras.append(rng.choice(PRICE[s]).format(x=money(n, split, rng)))
    if rng.random() < 0.5:
        j = rng.choice([True, False, None])
        if j is not None:
            facts["publicado_joue"] = j
        extras.append(rng.choice(JOUE[j][s]))
    if rng.random() < 0.45:
        d = today + timedelta(days=rng.choice([0, 1, 1, 3, 10, 25, 60]))
        facts["data_inicio_procedimento"] = d.isoformat()
        extras.append(rng.choice(START[s]).format(d=when(d, today, split, rng)))
    if rng.random() < 0.3:
        extras.append(rng.choice(ASIDES[s]))
    rng.shuffle(extras)
    target = rng.choice(TARGETS[s])
    if s == 0:
        question = " ".join([lead] + extras + [target])
    else:
        layout = rng.choice(["question_first", "greeting"])
        question = " ".join([target, lead] + extras) if layout == "question_first" else " ".join(["Olá, preciso de ajuda.", lead] + extras + [target])
    return question, today.isoformat(), facts


def generate(store=None, held_doc=None):
    """{relative path: bytes} of training/data-v5. Pure: same code -> same bytes (the store is not read; the task uses no law text)."""
    files, index = {}, {"version": VERSION, "seed": SEED, "split": {}, "files": {}}
    sch, seen = schema(), set()
    for split, n in (("train", N_TRAIN), ("held_out", N_HELD)):
        rng = random.Random(f"{SEED}|{split}")
        rows, guard = [], 0
        while len(rows) < n and guard < n * 20:
            guard += 1
            question, today, facts = one(rng, split)
            p = prompt(question, today)
            if p in seen:
                continue
            seen.add(p)
            rows.append(json.dumps({"id": f"{TASK}:{sha256_text(p)[:16]}", "task": TASK, "prompt": p, "answer": answer(facts), "sources": [],
                                    "schema": sch}, ensure_ascii=False))
        rel = f"{TASK}/{split}.jsonl"
        files[rel] = ("\n".join(rows) + "\n").encode("utf-8")
        index["split"][split] = len(rows)
    for rel in sorted(files):
        index["files"][rel] = {"sha256": hashlib.sha256(files[rel]).hexdigest(), "lines": files[rel].count(b"\n")}
    files["INDEX.json"] = (json.dumps(index, ensure_ascii=False, sort_keys=True, indent=1) + "\n").encode("utf-8")
    return files


def real():
    """training/real-questions/factos-v1.jsonl: the hand-written questions in the reader's prompt format (no template here wrote them)."""
    src = REAL / "factos-v1.questions.jsonl"
    rows, sch = [], schema()
    for line in src.read_text(encoding="utf-8").splitlines():
        q = json.loads(line)
        rows.append(json.dumps({"id": q["id"], "task": TASK, "prompt": prompt(q["pergunta"], q["hoje"]), "answer": answer(q["factos"]),
                                "sources": [], "schema": sch}, ensure_ascii=False))
    out = REAL / "factos-v1.jsonl"
    out.write_text("\n".join(rows) + "\n", encoding="utf-8")
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("cmd", choices=["generate", "real"]); ap.add_argument("--out", default=str(DATA))
    a = ap.parse_args()
    if a.cmd == "real":
        print(real())
        return
    files = generate()
    mt.write(files, Path(a.out))
    print(json.loads(files["INDEX.json"])["split"])


if __name__ == "__main__":
    main()
